from typing import List

class SolutionMemoized:
    def minPathSum(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        memo = {}

        def dfs(r: int, c: int) -> int:
            if r == m or c == n:
                return float("inf")
            if r == m - 1 and c == n - 1:
                return grid[r][c]
            if (r, c) not in memo:
                memo[(r, c)] = grid[r][c] + min(dfs(r + 1, c), dfs(r, c + 1))
            return memo[(r, c)]

        return dfs(0, 0)

